package com.tekwatt.audit.service;import com.tekwatt.audit.dto.*;import com.tekwatt.audit.entity.AuditEvent;import com.tekwatt.audit.repository.AuditEventRepository;import java.time.*;import java.util.UUID;import org.springframework.data.domain.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;@Service@Transactional public class AuditService{private final AuditEventRepository repo;public AuditService(AuditEventRepository r){repo=r;}public AuditEventResponse create(CreateAuditEventRequest r){return AuditEventResponse.from(repo.save(new AuditEvent(r.tenantId(),r.actorType(),r.actorId(),r.action(),r.resourceType(),r.resourceId(),r.outcome(),r.ipAddress(),r.userAgent(),r.correlationId(),r.sourceService(),r.details(),r.occurredAt())));}@Transactional(readOnly=true)public AuditEventResponse get(UUID id){return AuditEventResponse.from(repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Audit event not found")));}@Transactional(readOnly=true)public Page<AuditEventResponse>search(UUID tenant,String action,String resource,Instant from,Instant to,Pageable pageable){Instant end=to==null?Instant.now():to;Instant start=from==null?end.minus(Duration.ofDays(30)):from;if(start.isAfter(end))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"from must not be after to");return repo.search(tenant,action,resource,start,end,pageable).map(AuditEventResponse::from);}}
